package co.nexus.research;
import android.app.Activity;import android.os.*;import android.widget.*;import android.graphics.*;import android.view.View;import android.util.AtomicFile;import java.io.*;import java.util.Locale;import java.util.concurrent.*;
public final class CognitiveActivity extends Activity {
 final Handler ui=new Handler(Looper.getMainLooper());final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();volatile boolean running,training;volatile long generation;CognitiveCore core;CognitiveArena arena;AtomicFile checkpoint;TextView status;Board board;String loadNote="";long evaluationEpisodes,evaluationWins;
 @Override public void onCreate(Bundle b){super.onCreate(b);checkpoint=new AtomicFile(new File(getFilesDir(),"nx14.bin"));LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(16,24,16,16);status=new TextView(this);status.setTextSize(16);status.setText("Inicializando 64 expertos…");root.addView(status);board=new Board();root.addView(board,new LinearLayout.LayoutParams(-1,0,1));button(root,"Aprender sin ejemplos",()->start(true));button(root,"Evaluar sin aprender",()->start(false));button(root,"Detener y guardar",()->stop());setContentView(root);worker.execute(()->{try(InputStream in=checkpoint.openRead()){core=CognitiveCore.read(in);loadNote="Modelo recuperado";}catch(IOException ex){core=new CognitiveCore(14);loadNote="Modelo inicial";}arena=new CognitiveArena(14);render(null);});}
 void button(LinearLayout root,String text,Runnable r){Button b=new Button(this);b.setText(text);b.setOnClickListener(v->r.run());root.addView(b);}
 void start(boolean train){long id=++generation;running=true;training=train;worker.execute(()->{if(generation!=id)return;arena=new CognitiveArena((train?core.episodes:evaluationEpisodes)+(train?1400:90000));tick(id,train);});}
 void tick(long id,boolean train){if(!running||generation!=id||core==null)return;PowerManager pm=getSystemService(PowerManager.class);if(Build.VERSION.SDK_INT>=29&&pm.getCurrentThermalStatus()>=PowerManager.THERMAL_STATUS_SEVERE){running=false;save();loadNote="Pausa térmica";render(null);return;}if(arena.done)arena=new CognitiveArena((train?core.episodes:evaluationEpisodes)+(train?1400:90000));CognitiveCore.Observation o=arena.observe();CognitiveCore.Decision d=core.choose(o,train);float[] outcome=arena.step(d.action);if(train)core.learn(o,d.action,outcome);if(arena.done){if(train){core.episodes++;if(arena.won)core.wins++;if(core.episodes%10==0)save();}else{evaluationEpisodes++;if(arena.won)evaluationWins++;}}render(d);if(running&&generation==id)worker.schedule(()->tick(id,train),train?90:260,TimeUnit.MILLISECONDS);}
 void stop(){running=false;generation++;if(!worker.isShutdown())worker.execute(()->{if(core!=null){save();render(null);}});}
 void save(){FileOutputStream out=null;try{out=checkpoint.startWrite();core.write(out);checkpoint.finishWrite(out);loadNote="Checkpoint guardado";}catch(IOException ex){if(out!=null)checkpoint.failWrite(out);loadNote="Error guardando checkpoint";}}
 void render(CognitiveCore.Decision d){String t="NEXUS 0.14 · Laboratorio cognitivo\n64 expertos × 128 × 128 → 4 | "+(running?(training?"Aprendizaje":"Evaluación"):"Detenido")+"\nEpisodios: "+core.episodes+" | Éxitos: "+core.wins+" | Actualizaciones: "+core.updates+"\nEvaluación: "+evaluationWins+"/"+evaluationEpisodes+"\nSalud: "+arena.health+" | Energía: "+arena.energy+" | Kits: "+arena.kits+"\n"+arena.event+"\n"+(d==null?"":String.format(Locale.ROOT,"U %.2f | S %.2f | C %.2f | I %.2f | Incert. %.2f\n",d.heads[0],d.heads[1],d.heads[2],d.heads[3],d.uncertainty))+loadNote;int[] cells={arena.pos,arena.goal,arena.resource,arena.kit,arena.mount,arena.beacon};ui.post(()->{if(isDestroyed())return;status.setText(t);board.cells=cells;board.invalidate();});}
 @Override protected void onPause(){stop();super.onPause();}@Override protected void onDestroy(){running=false;generation++;worker.shutdown();super.onDestroy();}
 final class Board extends View{final Paint p=new Paint();int[] cells={0,63,7,12,21,35};Board(){super(CognitiveActivity.this);}protected void onDraw(Canvas c){float d=Math.min(getWidth(),getHeight())/8f;p.setTextSize(d*.35f);String[] names={"A","G","E","K","V","B"};int[] colors={0xff22ddcc,0xff55cc77,0xffe4af45,0xffe77f8c,0xff6f9aee,0xffa88bea};for(int i=0;i<64;i++){float x=i%8*d,y=i/8*d;p.setColor(0xff223344);c.drawRect(x+1,y+1,x+d-1,y+d-1,p);for(int j=5;j>=0;j--)if(cells[j]==i){p.setColor(colors[j]);c.drawRect(x+3,y+3,x+d-3,y+d-3,p);p.setColor(0xff101820);c.drawText(names[j],x+d*.35f,y+d*.65f,p);}}}}
}
